-- FoodOnlines original catalog restoration for phpMyAdmin / MySQL 8+
-- IMPORTANT: Back up the database before import.
-- Select the correct database: u517869682_FoodonlineDB
-- Import this file through phpMyAdmin. Do not edit live IDs manually.
-- This script inserts only missing catalog records. Existing rows are preserved.
-- The existing category slug `dried-food` is preserved and is never inserted, updated, or deleted here.
-- Re-running this script should create zero duplicates.
-- No user, administrator, order, payment, cart, inventory, review, return, support, address, token, or runtime-media table is touched.
-- Source: src/data/home.ts plus current Laravel catalog schema and LegacyCategoryBackfill.
-- Canonical scope: 16 categories, 1 alias, 9 brands, 240 products, 720 variants, 225 compatible product-media rows, 0 nutrition rows.
-- The 720 display-only listing clones are intentionally excluded.
-- The 735 generated data: media references and 240 explicitly sample nutrition blocks are intentionally excluded.

USE `u517869682_FoodonlineDB`;
SET NAMES utf8mb4;
START TRANSACTION;

SET @foodonlines_dried_food_before_count := (SELECT COUNT(*) FROM `categories` WHERE `slug` = 'dried-food');
SET @foodonlines_dried_food_before_hash := (
  SELECT MD5(CONCAT_WS('|', `uuid`, COALESCE(`parent_id`, ''), `name`, `slug`, COALESCE(`description`, ''), `status`, `visibility`, `sort_order`, `depth`, `path`, COALESCE(`image_path`, ''), `is_featured`, `show_in_navigation`, `show_on_homepage`, COALESCE(`deleted_at`, '')))
  FROM `categories` WHERE `slug` = 'dried-food' LIMIT 1
);

DROP TEMPORARY TABLE IF EXISTS `tmp_foodonlines_restore_guard`;
DROP TEMPORARY TABLE IF EXISTS `tmp_foodonlines_restore_aliases`;
DROP TEMPORARY TABLE IF EXISTS `tmp_foodonlines_restore_media`;
DROP TEMPORARY TABLE IF EXISTS `tmp_foodonlines_restore_variants`;
DROP TEMPORARY TABLE IF EXISTS `tmp_foodonlines_restore_products`;
DROP TEMPORARY TABLE IF EXISTS `tmp_foodonlines_restore_brands`;
DROP TEMPORARY TABLE IF EXISTS `tmp_foodonlines_restore_categories`;

CREATE TEMPORARY TABLE `tmp_foodonlines_restore_guard` (`id` TINYINT UNSIGNED NOT NULL PRIMARY KEY);

CREATE TEMPORARY TABLE `tmp_foodonlines_restore_categories` (
  `uuid` CHAR(36) NOT NULL UNIQUE, `name` VARCHAR(160) NOT NULL, `slug` VARCHAR(160) NOT NULL PRIMARY KEY,
  `sort_order` INT UNSIGNED NOT NULL, `image_path` VARCHAR(2048) NOT NULL,
  `is_featured` TINYINT(1) NOT NULL, `show_in_navigation` TINYINT(1) NOT NULL, `show_on_homepage` TINYINT(1) NOT NULL
);
CREATE TEMPORARY TABLE `tmp_foodonlines_restore_brands` (
  `uuid` CHAR(36) NOT NULL UNIQUE, `name` VARCHAR(150) NOT NULL, `slug` VARCHAR(160) NOT NULL PRIMARY KEY, `sort_order` INT UNSIGNED NOT NULL
);
CREATE TEMPORARY TABLE `tmp_foodonlines_restore_products` (
  `uuid` CHAR(36) NOT NULL UNIQUE, `category_slug` VARCHAR(160) NOT NULL, `brand_slug` VARCHAR(160) NOT NULL,
  `name` VARCHAR(255) NOT NULL, `slug` VARCHAR(160) NOT NULL PRIMARY KEY, `description` TEXT NULL,
  `country_of_origin_code` CHAR(2) NULL, `storage_instructions` TEXT NULL, `is_featured` TINYINT(1) NOT NULL
);
CREATE TEMPORARY TABLE `tmp_foodonlines_restore_variants` (
  `uuid` CHAR(36) NOT NULL UNIQUE, `product_slug` VARCHAR(160) NOT NULL, `title` VARCHAR(150) NOT NULL,
  `sku` VARCHAR(100) NOT NULL PRIMARY KEY, `size_label` VARCHAR(100) NULL, `net_content_value` DECIMAL(12,3) NULL,
  `net_content_unit` VARCHAR(10) NULL, `pack_count` INT UNSIGNED NOT NULL, `price_amount` DECIMAL(12,2) NOT NULL,
  `compare_at_price_amount` DECIMAL(12,2) NULL, `currency_code` CHAR(3) NOT NULL,
  `availability_status` VARCHAR(20) NOT NULL, `is_default` TINYINT(1) NOT NULL, `is_active` TINYINT(1) NOT NULL, `sort_order` INT UNSIGNED NOT NULL
);
CREATE TEMPORARY TABLE `tmp_foodonlines_restore_media` (
  `product_slug` VARCHAR(160) NOT NULL, `path` VARCHAR(2048) NOT NULL, `alt_text` VARCHAR(255) NULL,
  `image_fit` VARCHAR(10) NOT NULL, `is_primary` TINYINT(1) NOT NULL, `sort_order` INT UNSIGNED NOT NULL,
  UNIQUE KEY `tmp_restore_media_identity` (`product_slug`, `path`(500))
);
CREATE TEMPORARY TABLE `tmp_foodonlines_restore_aliases` (
  `category_slug` VARCHAR(160) NOT NULL, `alias_slug` VARCHAR(160) NOT NULL PRIMARY KEY,
  `redirect_code` SMALLINT UNSIGNED NOT NULL, `is_active` TINYINT(1) NOT NULL
);







-- Preflight: deliberately trigger a duplicate-key error before catalog writes if a stable UUID/SKU/alias collides with another live identity.
SELECT 1 FROM DUAL WHERE
  EXISTS (SELECT 1 FROM `tmp_foodonlines_restore_categories` s JOIN `categories` c ON c.`uuid` = s.`uuid` WHERE c.`slug` <> s.`slug`)
  OR EXISTS (SELECT 1 FROM `tmp_foodonlines_restore_categories` s JOIN `categories` c ON c.`slug` = s.`slug` WHERE c.`deleted_at` IS NOT NULL)
  OR EXISTS (SELECT 1 FROM `tmp_foodonlines_restore_categories` s JOIN `category_aliases` a ON a.`alias_slug` = s.`slug` LEFT JOIN `categories` c ON c.`slug` = s.`slug` WHERE c.`id` IS NULL)
  OR EXISTS (SELECT 1 FROM `tmp_foodonlines_restore_brands` s JOIN `brands` b ON b.`uuid` = s.`uuid` WHERE b.`slug` <> s.`slug`)
  OR EXISTS (SELECT 1 FROM `tmp_foodonlines_restore_products` s JOIN `products` p ON p.`uuid` = s.`uuid` WHERE p.`slug` <> s.`slug`)
  OR EXISTS (SELECT 1 FROM `tmp_foodonlines_restore_variants` s JOIN `product_variants` v ON v.`uuid` = s.`uuid` WHERE v.`sku` <> s.`sku`)
  OR EXISTS (SELECT 1 FROM `tmp_foodonlines_restore_variants` s JOIN `product_variants` v ON v.`sku` = s.`sku` JOIN `products` p ON p.`id` = v.`product_id` WHERE p.`slug` <> s.`product_slug`)
  OR EXISTS (SELECT 1 FROM `tmp_foodonlines_restore_aliases` s JOIN `category_aliases` a ON a.`alias_slug` = s.`alias_slug` JOIN `categories` c ON c.`id` = a.`category_id` WHERE c.`slug` <> s.`category_slug`)
LIMIT 1;

  `uuid`, `parent_id`, `name`, `slug`, `description`, `status`, `visibility`, `sort_order`, `depth`, `path`,
  `image_path`, `icon_path`, `desktop_banner_path`, `mobile_banner_path`, `is_featured`, `show_in_navigation`,
  `show_on_homepage`, `default_sort`, `meta_title`, `meta_description`, `canonical_url`, `robots_index`,
  `robots_follow`, `published_at`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`
)
SELECT s.`uuid`, NULL, s.`name`, s.`slug`, NULL, 'published', 'public', s.`sort_order`, 0, s.`slug`,
  s.`image_path`, NULL, NULL, NULL, s.`is_featured`, s.`show_in_navigation`, s.`show_on_homepage`, 'featured',
  NULL, NULL, NULL, 1, 1, CURRENT_TIMESTAMP, NULL, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, NULL
FROM `tmp_foodonlines_restore_categories` s
WHERE NOT EXISTS (SELECT 1 FROM `categories` c WHERE c.`slug` = s.`slug`)
  AND NOT EXISTS (SELECT 1 FROM `categories` c WHERE c.`uuid` = s.`uuid`);
SET @foodonlines_categories_inserted := ROW_COUNT();

SELECT c.`id`, s.`alias_slug`, s.`redirect_code`, s.`is_active`, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM `tmp_foodonlines_restore_aliases` s
JOIN `categories` c ON c.`slug` = s.`category_slug` AND c.`deleted_at` IS NULL
WHERE NOT EXISTS (SELECT 1 FROM `category_aliases` a WHERE a.`alias_slug` = s.`alias_slug`)
  AND NOT EXISTS (SELECT 1 FROM `categories` live_slug WHERE live_slug.`slug` = s.`alias_slug`);
SET @foodonlines_aliases_inserted := ROW_COUNT();

SELECT s.`uuid`, s.`name`, s.`slug`, NULL, NULL, 1, s.`sort_order`, NULL, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM `tmp_foodonlines_restore_brands` s
WHERE NOT EXISTS (SELECT 1 FROM `brands` b WHERE b.`slug` = s.`slug`)
  AND NOT EXISTS (SELECT 1 FROM `brands` b WHERE b.`uuid` = s.`uuid`);
SET @foodonlines_brands_inserted := ROW_COUNT();

  `uuid`, `category_id`, `brand_id`, `name`, `slug`, `description`, `meta_title`, `meta_description`,
  `canonical_url`, `robots_index`, `robots_follow`, `country_of_origin_code`, `storage_type`, `ingredients_text`,
  `allergen_statement`, `storage_instructions`, `status`, `is_featured`, `published_at`, `created_by`, `updated_by`, `created_at`, `updated_at`
)
SELECT s.`uuid`, c.`id`, b.`id`, s.`name`, s.`slug`, s.`description`, NULL, NULL, NULL, 1, 1,
  s.`country_of_origin_code`, NULL, NULL, NULL, s.`storage_instructions`, 'published', s.`is_featured`,
  CURRENT_TIMESTAMP, NULL, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM `tmp_foodonlines_restore_products` s
JOIN `categories` c ON c.`slug` = s.`category_slug` AND c.`deleted_at` IS NULL
JOIN `brands` b ON b.`slug` = s.`brand_slug`
WHERE NOT EXISTS (SELECT 1 FROM `products` p WHERE p.`slug` = s.`slug`)
  AND NOT EXISTS (SELECT 1 FROM `products` p WHERE p.`uuid` = s.`uuid`);
SET @foodonlines_products_inserted := ROW_COUNT();

  `uuid`, `product_id`, `title`, `sku`, `gtin`, `size_label`, `net_content_value`, `net_content_unit`,
  `pack_count`, `package_type`, `price_amount`, `compare_at_price_amount`, `currency_code`, `availability_status`,
  `is_default`, `is_active`, `sort_order`, `created_at`, `updated_at`
)
SELECT s.`uuid`, p.`id`, s.`title`, s.`sku`, NULL, s.`size_label`, s.`net_content_value`, s.`net_content_unit`,
  s.`pack_count`, NULL, s.`price_amount`, s.`compare_at_price_amount`, s.`currency_code`, s.`availability_status`,
  CASE WHEN s.`is_default` = 1 AND NOT EXISTS (
    SELECT 1 FROM `product_variants` existing_default
    WHERE existing_default.`product_id` = p.`id` AND existing_default.`is_active` = 1 AND existing_default.`is_default` = 1
  ) THEN 1 ELSE 0 END,
  s.`is_active`, s.`sort_order`, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM `tmp_foodonlines_restore_variants` s
JOIN `products` p ON p.`slug` = s.`product_slug`
WHERE NOT EXISTS (SELECT 1 FROM `product_variants` v WHERE v.`sku` = s.`sku`)
  AND NOT EXISTS (SELECT 1 FROM `product_variants` v WHERE v.`uuid` = s.`uuid`)
ORDER BY s.`is_default` ASC, s.`sort_order` ASC;
SET @foodonlines_variants_inserted := ROW_COUNT();

SELECT p.`id`, s.`path`, s.`alt_text`, s.`image_fit`,
  CASE WHEN s.`is_primary` = 1 AND NOT EXISTS (SELECT 1 FROM `product_media` existing_primary WHERE existing_primary.`product_id` = p.`id` AND existing_primary.`is_primary` = 1) THEN 1 ELSE 0 END,
  s.`sort_order`, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM `tmp_foodonlines_restore_media` s
JOIN `products` p ON p.`slug` = s.`product_slug`
WHERE NOT EXISTS (SELECT 1 FROM `product_media` m WHERE m.`product_id` = p.`id` AND m.`path` = s.`path`)
ORDER BY s.`is_primary` DESC, s.`sort_order` ASC;
SET @foodonlines_media_inserted := ROW_COUNT();
SET @foodonlines_nutrition_inserted := 0;

-- Post-insert relationship guard. Any unresolved or incorrect source relationship deliberately raises a duplicate-key error before COMMIT.
SELECT 1 FROM DUAL WHERE
  EXISTS (SELECT 1 FROM `tmp_foodonlines_restore_categories` s LEFT JOIN `categories` c ON c.`slug` = s.`slug` WHERE c.`id` IS NULL OR c.`deleted_at` IS NOT NULL OR c.`status` <> 'published' OR c.`published_at` IS NULL OR c.`visibility` <> 'public' OR c.`show_in_navigation` <> 1 OR c.`show_on_homepage` <> 1)
  OR EXISTS (SELECT 1 FROM `tmp_foodonlines_restore_brands` s LEFT JOIN `brands` b ON b.`slug` = s.`slug` WHERE b.`id` IS NULL OR b.`is_active` <> 1)
  OR EXISTS (SELECT 1 FROM `tmp_foodonlines_restore_products` s LEFT JOIN `products` p ON p.`slug` = s.`slug` LEFT JOIN `categories` c ON c.`id` = p.`category_id` LEFT JOIN `brands` b ON b.`id` = p.`brand_id` WHERE p.`id` IS NULL OR p.`status` <> 'published' OR p.`published_at` IS NULL OR c.`id` IS NULL OR c.`slug` <> s.`category_slug` OR b.`id` IS NULL OR b.`slug` <> s.`brand_slug`)
  OR EXISTS (SELECT 1 FROM `tmp_foodonlines_restore_variants` s LEFT JOIN `product_variants` v ON v.`sku` = s.`sku` LEFT JOIN `products` p ON p.`id` = v.`product_id` WHERE v.`id` IS NULL OR p.`id` IS NULL OR p.`slug` <> s.`product_slug` OR v.`is_active` <> 1 OR v.`availability_status` <> 'in_stock' OR v.`currency_code` <> 'USD' OR v.`price_amount` <> s.`price_amount`)
  OR EXISTS (SELECT 1 FROM `tmp_foodonlines_restore_media` s JOIN `products` p ON p.`slug` = s.`product_slug` LEFT JOIN `product_media` m ON m.`product_id` = p.`id` AND m.`path` = s.`path` WHERE m.`id` IS NULL)
  OR EXISTS (SELECT 1 FROM `tmp_foodonlines_restore_products` s JOIN `products` p ON p.`slug` = s.`slug` LEFT JOIN `product_variants` v ON v.`product_id` = p.`id` AND v.`is_active` = 1 AND v.`is_default` = 1 GROUP BY p.`id` HAVING COUNT(v.`id`) <> 1)
  OR EXISTS (SELECT 1 FROM `tmp_foodonlines_restore_aliases` s WHERE NOT EXISTS (SELECT 1 FROM `categories` live_slug WHERE live_slug.`slug` = s.`alias_slug`) AND NOT EXISTS (SELECT 1 FROM `category_aliases` a JOIN `categories` c ON c.`id` = a.`category_id` WHERE a.`alias_slug` = s.`alias_slug` AND c.`slug` = s.`category_slug`))
LIMIT 1;

COMMIT;

SET @foodonlines_dried_food_after_count := (SELECT COUNT(*) FROM `categories` WHERE `slug` = 'dried-food');
SET @foodonlines_dried_food_after_hash := (
  SELECT MD5(CONCAT_WS('|', `uuid`, COALESCE(`parent_id`, ''), `name`, `slug`, COALESCE(`description`, ''), `status`, `visibility`, `sort_order`, `depth`, `path`, COALESCE(`image_path`, ''), `is_featured`, `show_in_navigation`, `show_on_homepage`, COALESCE(`deleted_at`, '')))
  FROM `categories` WHERE `slug` = 'dried-food' LIMIT 1
);

SELECT 'rows_inserted_this_run' AS `check_name`,
  @foodonlines_categories_inserted AS `categories`, @foodonlines_aliases_inserted AS `category_aliases`,
  @foodonlines_brands_inserted AS `brands`, @foodonlines_products_inserted AS `products`,
  @foodonlines_variants_inserted AS `product_variants`, @foodonlines_media_inserted AS `product_media`,
  @foodonlines_nutrition_inserted AS `product_nutrition_facts`;

SELECT 'source_rows_resolved' AS `check_name`,
  (SELECT COUNT(*) FROM `tmp_foodonlines_restore_categories` s JOIN `categories` c ON c.`slug` = s.`slug` AND c.`deleted_at` IS NULL) AS `categories_resolved`,
  (SELECT COUNT(*) FROM `tmp_foodonlines_restore_brands` s JOIN `brands` b ON b.`slug` = s.`slug`) AS `brands_resolved`,
  (SELECT COUNT(*) FROM `tmp_foodonlines_restore_products` s JOIN `products` p ON p.`slug` = s.`slug`) AS `products_resolved`,
  (SELECT COUNT(*) FROM `tmp_foodonlines_restore_variants` s JOIN `product_variants` v ON v.`sku` = s.`sku`) AS `variants_resolved`,
  (SELECT COUNT(*) FROM `tmp_foodonlines_restore_media` s JOIN `products` p ON p.`slug` = s.`product_slug` JOIN `product_media` m ON m.`product_id` = p.`id` AND m.`path` = s.`path`) AS `media_resolved`;

SELECT 'dried_food_preserved' AS `check_name`,
  @foodonlines_dried_food_before_count AS `before_count`, @foodonlines_dried_food_after_count AS `after_count`,
  (@foodonlines_dried_food_before_count = @foodonlines_dried_food_after_count AND @foodonlines_dried_food_before_hash <=> @foodonlines_dried_food_after_hash) AS `unchanged`;

SELECT 'source_scope_integrity' AS `check_name`,
  (SELECT COUNT(*) FROM (SELECT p.`slug` FROM `tmp_foodonlines_restore_products` s JOIN `products` p ON p.`slug` = s.`slug` GROUP BY p.`slug` HAVING COUNT(*) > 1) duplicate_products) AS `duplicate_product_slugs`,
  (SELECT COUNT(*) FROM (SELECT v.`sku` FROM `tmp_foodonlines_restore_variants` s JOIN `product_variants` v ON v.`sku` = s.`sku` GROUP BY v.`sku` HAVING COUNT(*) > 1) duplicate_variants) AS `duplicate_variant_skus`,
  (SELECT COUNT(*) FROM `tmp_foodonlines_restore_variants` s LEFT JOIN `product_variants` v ON v.`sku` = s.`sku` WHERE v.`product_id` IS NULL) AS `orphan_variants`,
  (SELECT COUNT(*) FROM `tmp_foodonlines_restore_media` s LEFT JOIN `products` p ON p.`slug` = s.`product_slug` WHERE p.`id` IS NULL) AS `orphan_media`;

DROP TEMPORARY TABLE IF EXISTS `tmp_foodonlines_restore_aliases`;
DROP TEMPORARY TABLE IF EXISTS `tmp_foodonlines_restore_media`;
DROP TEMPORARY TABLE IF EXISTS `tmp_foodonlines_restore_variants`;
DROP TEMPORARY TABLE IF EXISTS `tmp_foodonlines_restore_products`;
DROP TEMPORARY TABLE IF EXISTS `tmp_foodonlines_restore_brands`;
DROP TEMPORARY TABLE IF EXISTS `tmp_foodonlines_restore_categories`;
DROP TEMPORARY TABLE IF EXISTS `tmp_foodonlines_restore_guard`;

